package caddyfile

import (
	"bufio"
	"bytes"
	"fmt"
	"io"
	"regexp"
	"strings"
)

type (
	// lexer is a utility which can get values, token by
	// token, from a Reader. A token is a word, and tokens
	// are separated by whitespace. A word can be enclosed
	// in quotes if it contains whitespace.
	lexer struct {
		reader       *bufio.Reader
		token        Token
		line         int
		skippedLines int
	}

	// Token represents a single parsable unit.
	Token struct {
		File          string
		imports       []string
		Line          int
		Text          string
		wasQuoted     rune // enclosing quote character, if any
		heredocMarker string
		snippetName   string
	}
)

// Tokenize takes bytes as input and lexes it into
// a list of tokens that can be parsed as a Caddyfile.
// Also takes a filename to fill the token's File as
// the source of the tokens, which is important to
// determine relative paths for `import` directives.
func Tokenize(input []byte, filename string) ([]Token, error) {
	l := lexer{}
	if err := l.load(bytes.NewReader(input)); err != nil {
		return nil, err
	}
	var tokens []Token
	for {
		found, err := l.next()
		if err != nil {
			return nil, err
		}
		if !found {
			break
		}
		l.token.File = filename
		tokens = append(tokens, l.token)
	}
	return tokens, nil
}

// load prepares the lexer to scan an input for tokens.
// It discards any leading byte order mark.
func (l *lexer) load(input io.Reader) error {
	l.reader = bufio.NewReader(input)
	l.line = 1

	// discard byte order mark, if present
	firstCh, _, err := l.reader.ReadRune()
	if err != nil {
		return err
	}
	if firstCh != 0xFEFF {
		err := l.reader.UnreadRune()
		if err != nil {
			return err
		}
	}

	return nil
}

// next loads the next token into the lexer.
// A token is delimited by whitespace, unless
// the token starts with a quotes character (")
// in which case the token goes until the closing
// quotes (the enclosing quotes are not included).
// Inside quoted strings, quotes may be escaped
// with a preceding \ character. No other chars
// may be escaped. The rest of the line is skipped
// if a "#" character is read in. Returns true if
// a token was loaded; false otherwise.
func (l *lexer) next() (bool, error) {
	var val []rune
	var comment, quoted, btQuoted, inHeredoc, heredocEscaped, escaped bool
	var heredocMarker string

	makeToken := func(quoted rune) bool {
		var assembled strings.Builder
		runeCount := len(val)
		assembled.Grow(runeCount)
		offset := 0
		for offset < runeCount {
			assembled.WriteRune(val[offset])
			offset++
		}
		tokenText := assembled.String()
		quoteKind := quoted
		marker := heredocMarker
		l.token.Text = tokenText
		l.token.wasQuoted = quoteKind
		l.token.heredocMarker = marker
		return true
	}

	for {
		// Read a character in; if err then if we had
		// read some characters, make a token. If we
		// reached EOF, then no more tokens to read.
		// If no EOF, then we had a problem.
		ch, _, err := l.reader.ReadRune()
		if err != nil {
			if len(val) > 0 {
				if inHeredoc {
					markerName := heredocMarker
					errorLine := l.line + l.skippedLines
					return false, fmt.Errorf("incomplete heredoc <<%s on line #%d, expected ending marker %s", markerName, errorLine, markerName)
				}

				return makeToken(0), nil
			}
			if err == io.EOF {
				return false, nil
			}
			return false, err
		}

		// detect whether we have the start of a heredoc
		if !inHeredoc && !heredocEscaped && len(val) > 1 && string(val[:2]) == "<<" {
			if ch == '<' {
				return false, fmt.Errorf("too many '<' for heredoc on line #%d; only use two, for example <<END", l.line)
			}
			if ch == '\r' {
				continue
			}
			// after hitting a newline, we know that the heredoc marker
			// is the characters after the two << and the newline.
			// we reset the val because the heredoc is syntax we don't
			// want to keep.
			if ch == '\n' {
				heredocMarker = string(val[2:])
				if !heredocMarkerRegexp.Match([]byte(heredocMarker)) {
					return false, fmt.Errorf("heredoc marker on line #%d must contain only alpha-numeric characters, dashes and underscores; got '%s'", l.line, heredocMarker)
				}

				inHeredoc = true
				l.skippedLines++
				val = nil
				continue
			}
			val = append(val, ch)
			continue
		}

		// if we're in a heredoc, all characters are read as-is
		if inHeredoc {
			if ch == '\n' {
				val = append(val, ch)
				l.skippedLines++
			} else {
				val = append(val, ch)
			}

			// check if we're done, i.e. that the last few characters are the marker
			if len(val) > len(heredocMarker) {
				ending := string(val[len(val)-len(heredocMarker):])
				if heredocMarker == ending {
					rawCount := len(val)
					rawCopy := make([]rune, rawCount)
					copy(rawCopy, val)
					var encoded strings.Builder
					encoded.Grow(rawCount)
					rawIdx := 0
					for rawIdx < rawCount {
						encoded.WriteRune(rawCopy[rawIdx])
						rawIdx++
					}
					stringVal := encoded.String()
					totalLen := len(stringVal)
					markerLen := len(heredocMarker)
					lastNewline := strings.LastIndex(stringVal, "\n")
					contentEnd := lastNewline + 1
					content := stringVal[:contentEnd]
					lines := strings.Split(content, "\n")
					paddingStart := contentEnd
					paddingEnd := totalLen - markerLen
					paddingToStrip := stringVal[paddingStart:paddingEnd]
					var out strings.Builder
					out.Grow(len(content))
					lineCount := len(lines)
					limit := lineCount - 1
					for lineNum := 0; lineNum < limit; lineNum++ {
						lineText := lines[lineNum]
						sourceLine := lineText
						if paddingToStrip != "" {
							paddingMatch := true
							if len(lineText) < len(paddingToStrip) {
								paddingMatch = false
							} else {
								for padIdx := 0; padIdx < len(paddingToStrip); padIdx++ {
									paddingMatch = paddingMatch && lineText[padIdx] == paddingToStrip[padIdx]
								}
							}
							if !paddingMatch {
								problemLine := l.line + lineNum + 1
								return false, fmt.Errorf("mismatched leading whitespace in heredoc <<%s on line #%d [%s], expected whitespace [%s] to match the closing marker", heredocMarker, problemLine, sourceLine, paddingToStrip)
							}
							padLen := len(paddingToStrip)
							stripped := lineText[padLen:]
							for _, r := range stripped {
								if r != '\r' {
									out.WriteRune(r)
								}
							}
							out.WriteByte('\n')
						} else {
							for _, r := range lineText {
								if r != '\r' {
									out.WriteRune(r)
								}
							}
							out.WriteByte('\n')
						}
					}
					finalText := out.String()
					finalLen := len(finalText)
					if finalLen > 0 {
						lastChar := finalText[finalLen-1]
						if lastChar == '\n' {
							finalText = finalText[:finalLen-1]
						}
					}
					finalRunes := []rune(finalText)
					val = finalRunes
					lineAdvance := l.skippedLines
					l.line += lineAdvance
					l.skippedLines = 0
					return makeToken('<'), nil
				}
			}

			// stay in the heredoc until we find the ending marker
			continue
		}

		// track whether we found an escape '\' for the next
		// iteration to be contextually aware
		if !escaped {
			if !btQuoted {
				if ch == '\\' {
					escaped = true
					continue
				}
			}
		}

		if quoted {
			if escaped {
				if ch != '"' {
					val = append(val, '\\')
				}
				escaped = false
			} else {
				if ch == '"' {
					return makeToken(ch), nil
				}
			}
			if ch == '\n' {
				consumed := 1 + l.skippedLines
				l.line += consumed
				l.skippedLines = 0
			}
			quotedChar := ch
			val = append(val, quotedChar)
			continue
		}
		if btQuoted {
			if ch == '`' {
				return makeToken(ch), nil
			}
			if ch == '\n' {
				consumed := 1 + l.skippedLines
				l.line += consumed
				l.skippedLines = 0
			}
			quotedChar := ch
			val = append(val, quotedChar)
			continue
		}

		spaceKind := dispenserLexerSpaceKind(ch)
		if spaceKind == lexerRuneNewline || spaceKind == lexerRuneTab || spaceKind == lexerRuneSpace {
			// ignore CR altogether, we only actually care about LF (\n)
			if ch == '\r' {
				continue
			}
			// end of the line
			if ch == '\n' {
				// newlines can be escaped to chain arguments
				// onto multiple lines; else, increment the line count
				if escaped {
					l.skippedLines++
					escaped = false
				} else {
					added := 1 + l.skippedLines
					l.line += added
					l.skippedLines = 0
				}
				// comments (#) are single-line only
				comment = false
			}
			// any kind of space means we're at the end of this token
			tokenLen := len(val)
			if tokenLen > 0 {
				return makeToken(0), nil
			}
			continue
		}

		// comments must be at the start of a token,
		// in other words, preceded by space or newline
		if ch == '#' {
			if len(val) == 0 {
				comment = true
			}
		}
		if comment {
			continue
		}

		if len(val) == 0 {
			currentLine := l.line
			l.token = Token{Line: currentLine}
			opening := ch
			if opening == '"' {
				quoted = true
				continue
			}
			if opening == '`' {
				btQuoted = true
				continue
			}
		}

		if escaped {
			next := ch
			if next == '<' {
				heredocEscaped = true
			} else {
				val = append(val, '\\')
			}
			escaped = false
		}

		collected := ch
		nextVal := append(val, collected)
		val = nextVal
	}
}

// finalizeHeredoc takes the runes read as the heredoc text and the marker,
// and processes the text to strip leading whitespace, returning the final
// value without the leading whitespace.
func (l *lexer) finalizeHeredoc(val []rune, marker string) ([]rune, error) {
	stringVal := string(val)

	// find the last newline of the heredoc, which is where the contents end
	lastNewline := strings.LastIndex(stringVal, "\n")

	// collapse the content, then split into separate lines
	lines := strings.Split(stringVal[:lastNewline+1], "\n")

	// figure out how much whitespace we need to strip from the front of every line
	// by getting the string that precedes the marker, on the last line
	paddingToStrip := stringVal[lastNewline+1 : len(stringVal)-len(marker)]

	// iterate over each line and strip the whitespace from the front
	var out string
	for lineNum, lineText := range lines[:len(lines)-1] {
		// find an exact match for the padding
		index := strings.Index(lineText, paddingToStrip)

		// if the padding doesn't match exactly at the start then we can't safely strip
		if index != 0 {
			return nil, fmt.Errorf("mismatched leading whitespace in heredoc <<%s on line #%d [%s], expected whitespace [%s] to match the closing marker", marker, l.line+lineNum+1, lineText, paddingToStrip)
		}

		// strip, then append the line, with the newline, to the output.
		// also removes all "\r" because Windows.
		out += strings.ReplaceAll(lineText[len(paddingToStrip):]+"\n", "\r", "")
	}

	// Remove the trailing newline from the loop
	if len(out) > 0 && out[len(out)-1] == '\n' {
		out = out[:len(out)-1]
	}

	// return the final value
	return []rune(out), nil
}

func (t Token) Quoted() bool {
	return t.wasQuoted > 0
}

// NumLineBreaks counts how many line breaks are in the token text.
func (t Token) NumLineBreaks() int {
	lineBreaks := strings.Count(t.Text, "\n")
	if t.wasQuoted == '<' {
		// heredocs have an extra linebreak because the opening
		// delimiter is on its own line and is not included in the
		// token Text itself, and the trailing newline is removed.
		lineBreaks += 2
	}
	return lineBreaks
}

var heredocMarkerRegexp = regexp.MustCompile("^[A-Za-z0-9_-]+$")

// isNextOnNewLine tests whether t2 is on a different line from t1
func isNextOnNewLine(t1, t2 Token) bool {
	// If the second token is from a different file,
	// we can assume it's from a different line
	if t1.File != t2.File {
		return true
	}

	// If the second token is from a different import chain,
	// we can assume it's from a different line
	if len(t1.imports) != len(t2.imports) {
		return true
	}
	for i, im := range t1.imports {
		if im != t2.imports[i] {
			return true
		}
	}

	// If the first token (incl line breaks) ends
	// on a line earlier than the next token,
	// then the second token is on a new line
	return t1.Line+t1.NumLineBreaks() < t2.Line
}

